/* Popover, dropdown menu and select content on Radix: a bordered panel above the page. */
.popover { z-index: var(--z-drawer); min-width: 200px; max-width: min(360px, 92vw); padding: var(--s4); background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); box-shadow: var(--shadow-popover); animation: dialog-fade var(--fast) var(--ease); }
.popover:focus-visible { outline-offset: 2px; }
.menu-content { z-index: var(--z-drawer); min-width: 200px; padding: var(--s1) 0; background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); box-shadow: var(--shadow-popover); animation: dialog-fade var(--fast) var(--ease); }
.menu-content .menu-item { cursor: pointer; }
.menu-content .menu-item[data-highlighted] { background: var(--foreground); color: var(--background); outline: none; }
.menu-content .menu-item[data-disabled] { opacity: var(--opacity-disabled); pointer-events: none; }
.menu-content .menu-item[data-variant="danger"][data-highlighted] { background: var(--danger); }
.menu-label { padding: var(--s2) var(--s4); font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.menu-indicator { width: 14px; display: inline-flex; justify-content: center; }
.menu-item-check { display: flex; align-items: center; gap: var(--s3); }

/* ─── Dropdown menu: <details class="dropdown">; monoline.js closes it on Escape and outside click ─── */
.dropdown { position: relative; display: inline-block; }
.dropdown > summary { list-style: none; cursor: pointer; }
.dropdown > summary::-webkit-details-marker { display: none; }
.menu { position: absolute; inset-inline-start: 0; top: calc(100% + var(--s2)); z-index: var(--z-drawer); min-width: 200px; background: var(--background); border: 1px solid var(--foreground); padding: var(--s1) 0; }
.menu-end { inset-inline-start: auto; inset-inline-end: 0; }
.menu-item { overflow-wrap: anywhere; display: flex; justify-content: space-between; gap: var(--s5); width: 100%; padding: var(--s2) var(--s4); font-size: var(--text-sm); text-align: start; }
.menu-item:hover, .menu-item:focus-visible { background: var(--foreground); color: var(--background); outline-offset: -2px; }
.menu-item.danger:hover { background: var(--danger); color: var(--background); }
.menu-sep { border: 0; border-top: 1px solid var(--rule); margin: var(--s1) 0; }

source.content:
'use client';
import {
  createContext,
  forwardRef,
  useContext,
  useEffect,
  useRef,
  useState,
  type HTMLAttributes,
  type PointerEvent,
} from 'react';
import {Slot} from '../../utils/slot';
import {cx} from '../../utils/cx';
import {setRefs} from '../../utils/overlay';
import {
  MenuContent,
  MenuItem,
  MenuLabel,
  MenuRoot,
  MenuSeparator,
  openWith,
  useMenuCtx,
  type MenuContentProps,
  type MenuItemProps,
  type MenuProps,
} from '../dropdown-menu/menu';

const Point = createContext<(x: number, y: number) => void>(() => {});

/** The root of a right-click (or long-press) menu. Put a `ContextMenuTrigger` and a `ContextMenuContent` inside. */
export function ContextMenu({children, ...props}: MenuProps) {
  const [at, setAt] = useState({x: 0, y: 0});
  const dot = useRef<HTMLSpanElement | null>(null);
  return (
    <MenuRoot {...props} extra={{anchor: () => dot.current}}>
      <Point.Provider value={(x, y) => setAt({x, y})}>{children}</Point.Provider>
      <span
        ref={dot}
        aria-hidden="true"
        style={{position: 'fixed', left: at.x, top: at.y, width: 0, height: 0, pointerEvents: 'none'}}
      />
    </MenuRoot>
  );
}

/** The area that opens the menu when right-clicked or long-pressed; use `asChild` to make your own element the area. */
export const ContextMenuTrigger = forwardRef<
  HTMLSpanElement,
  HTMLAttributes<HTMLSpanElement> & {
    /** Render your own element instead of a span; it receives the props and handlers. */
    asChild?: boolean | undefined;
  }
>(function ContextMenuTrigger(
  {asChild, onContextMenu, onPointerDown, onPointerUp, onPointerMove, onPointerCancel, tabIndex, ...rest},
  ref,
) {
  const c = useMenuCtx(),
    at = useContext(Point);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const origin = useRef<{x: number; y: number} | null>(null);
  useEffect(() => () => clearTimeout(timer.current), []);
  const open = (x: number, y: number) => {
    at(x, y);
    openWith('panel');
    c.setOpen(true);
  };
  const Comp = asChild ? Slot : 'span';
  return (
    <Comp
      ref={(n: HTMLSpanElement | null) => setRefs(n, c.trigger, ref)}
      data-state={c.open ? 'open' : 'closed'}
      tabIndex={
        tabIndex ?? (asChild ? undefined : 0)
      } /* focusable, so the ContextMenu key and Shift+F10 (which the browser turns into a contextmenu event) reach it */
      {...rest}
      onContextMenu={(e: React.MouseEvent) => {
        onContextMenu?.(e as never);
        if (e.defaultPrevented) return;
        e.preventDefault();
        clearTimeout(timer.current);
        // Keyboard-invoked contextmenu (Shift+F10, the Menu key): some browsers report 0,0, so anchor to the trigger instead.
        if (e.clientX === 0 && e.clientY === 0) {
          const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
          open(r.left + r.width / 2, r.top + r.height / 2);
        } else open(e.clientX, e.clientY);
      }}
      onPointerDown={(e: PointerEvent) => {
        onPointerDown?.(e as never);
        if (e.pointerType === 'touch') {
          const {clientX: x, clientY: y} = e;
          origin.current = {x, y};
          clearTimeout(timer.current);
          timer.current = setTimeout(() => open(x, y), 700);
        }
      }}
      onPointerMove={(e: PointerEvent) => {
        onPointerMove?.(e as never);
        const o = origin.current;
        if (!o || Math.hypot(e.clientX - o.x, e.clientY - o.y) > 10) clearTimeout(timer.current);
      }}
      onPointerUp={(e: PointerEvent) => {
        onPointerUp?.(e as never);
        clearTimeout(timer.current);
      }}
      // A touch scroll ends in pointercancel, not pointerup: stop the long-press timer there too.
      onPointerCancel={(e: PointerEvent) => {
        onPointerCancel?.(e as never);
        clearTimeout(timer.current);
      }}
    />
  );
});

/** The floating panel that lists the menu entries, opened at the pointer. */
export const ContextMenuContent = forwardRef<HTMLDivElement, MenuContentProps>(function ContextMenuContent(
  {side = 'right', align = 'start', ...rest},
  ref,
) {
  return <MenuContent ref={ref} side={side} align={align} {...rest} />;
});

/** A thin line that separates groups of entries. */
export const ContextMenuSeparator = MenuSeparator;
/** A non-interactive heading for a group of entries. */
export const ContextMenuLabel = MenuLabel;
export interface ContextMenuItemProps extends MenuItemProps {
  /** `danger` highlights in the danger colour. */
  tone?: 'default' | 'danger' | undefined;
}
/** One action in the menu; call `onSelect` when it is chosen. */
export const ContextMenuItem = forwardRef<HTMLDivElement, ContextMenuItemProps>(function ContextMenuItem(
  {className, tone = 'default', ...rest},
  ref,
) {
  return <MenuItem ref={ref} data-variant={tone} className={cx('menu-item', className)} {...rest} />;
});

export {
  ContextMenu,
  ContextMenuTrigger,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuSeparator,
} from './context-menu';
export type {ContextMenuItemProps} from './context-menu';

